import re

from django.db import migrations, models

# Copie figée du format de inventory/addresses.py (une migration ne dépend pas du code courant).
ADDRESS_PATTERN = re.compile(
    r'^(?P<street>.+?)\s+(?P<house_number>\d+[A-Za-z]?)'
    r'(?:\s*(?:bte|bus|boîte)\s*(?P<box>\S+))?'
    r',\s*(?P<postal_code>\d{4,5})\s+(?P<city>[^,]+?)'
    r'(?:,\s*(?P<country>[^,]+))?$'
)
COUNTRY_CODES = {'belgique': 'BE', 'france': 'FR', 'pays-bas': 'NL', 'luxembourg': 'LU', 'allemagne': 'DE'}


def split_addresses(apps, schema_editor):
    """
    Découpe l'adresse libre des lieux existants (« Rue N, CP Ville, Pays »). Une adresse qui ne suit
    pas ce format est reprise telle quelle dans « Rue » : le lieu apparaît « Adresse à compléter ».
    Le champ address (adresse complète) n'est pas modifié.
    """
    Building = apps.get_model('inventory', 'Building')
    for building in Building.objects.all():
        text = ' '.join((building.address or '').split())
        match = ADDRESS_PATTERN.match(text)
        if match:
            parts = {key: (value or '').strip() for key, value in match.groupdict().items()}
            parts['country'] = COUNTRY_CODES.get(parts['country'].lower(), 'BE')
        else:
            parts = {'street': text[:255]}
        Building.objects.filter(pk=building.pk).update(**parts)


